import{_ as a,o as e,c as r,a2 as s}from"./chunks/framework.BWuWLRhz.js";const u=JSON.parse('{"title":"起始面板","description":"","frontmatter":{},"headers":[],"relativePath":"zh-TW/user-guide/settings/startup-panel.md","filePath":"zh-TW/user-guide/settings/startup-panel.md","lastUpdated":1785214938000}'),o={name:"zh-TW/user-guide/settings/startup-panel.md"};function n(l,t,i,d,h,p){return e(),r("div",null,[...t[0]||(t[0]=[s('<h1 id="起始面板" tabindex="-1">起始面板 <a class="header-anchor" href="#起始面板" aria-label="Permalink to &quot;起始面板&quot;">​</a></h1><p>搜尋框為空時，快速視窗結果清單上方顯示的一個標籤列，不用輸入查詢就能快速存取最近檔案、我的最愛和歷史記錄。</p><ul><li><strong>啟用起始面板</strong> —— 總開關;關閉後，不管下面各個標籤自己的設定如何，整個面板都不會啟用。</li></ul><p>四個子標籤:<strong>最近檔案</strong>、<strong>上次目錄</strong>、<strong>外掛標籤</strong> 和 <strong>標籤順序</strong>。</p><h2 id="最近檔案" tabindex="-1">最近檔案 <a class="header-anchor" href="#最近檔案" aria-label="Permalink to &quot;最近檔案&quot;">​</a></h2><ul><li><strong>啟用面板</strong> —— 勾選框;搜尋框為空時顯示該標籤。</li><li><strong>目錄</strong> —— 要監控的資料夾，每行一個(新增/編輯/刪除單行，以及批次文字編輯，和 <a href="./index-drives.html#排除規則">排除規則清單</a>是同一套互動)。可以是本機磁碟機、已掛接的網路磁碟機， 以及 WSL 路徑(<code>\\\\wsl$\\...</code> 或 <code>\\\\wsl.localhost\\...</code>)——會比對到你已經在 <a href="./index-drives.html">索引</a>裡設定並建過索引的對應項目。</li><li><strong>顯示的檔案數量上限</strong> —— 範圍 1–100，預設 10。</li><li><strong>時間範圍(分鐘)</strong> —— 只有在這個時間範圍內修改過的檔案才符合條件，疊加在上面的數量上限之上。 範圍 1–43200(30 天)，預設 60。</li></ul><p>每一項的第二行開頭會帶上一個相對時間——「X 秒/分鐘/小時/天前」——直接根據索引裡已經存好的檔案 最後修改時間算出來，不需要額外存取磁碟。小時和天這兩檔在餘下的分鐘/小時為 0 時會省略(比如顯示 「2小時前」而不是「2小時0分鐘前」)。</p><h2 id="上次目錄" tabindex="-1">上次目錄 <a class="header-anchor" href="#上次目錄" aria-label="Permalink to &quot;上次目錄&quot;">​</a></h2><ul><li><strong>啟用面板</strong> —— 勾選框，預設開啟。</li></ul><p>顯示 SwiftList 接管系統檔案開啟/儲存對話方塊時，最後停留過的目錄內容——不用記路徑，就能快速回到 剛才用檔案選擇器瀏覽過的地方。真正的索引會用到的隱藏/系統檔案篩選和 <a href="./index-drives.html#排除規則">排除規則</a>在這裡同樣生效，所以不會出現 <code>$RECYCLE.BIN</code> 這類東西。本次 執行還沒有觸發過、該目錄已經不存在、或者就是桌面(經常只是預設落腳點，不算真的「去過」)時，這 個標籤完全不會出現。</p><h2 id="外掛標籤" tabindex="-1">外掛標籤 <a class="header-anchor" href="#外掛標籤" aria-label="Permalink to &quot;外掛標籤&quot;">​</a></h2><p>外掛提供的標籤(如歷史記錄、我的最愛)在面板裡各自帶一個 <strong>×</strong> 按鈕，可以先把它隱藏起來。這只是 面板本地的「先不顯示」選擇——和在<a href="./plugins.html">外掛</a>頁面裡把該外掛元件本身停用是兩回事，後者是讓 它徹底不參與使用。透過 × 關閉的標籤會按提供它的外掛分組顯示在這裡，未勾選;勾上即可重新開啟。</p><p>只有外掛層面已啟用的標籤才會出現在這個清單裡——在<a href="./plugins.html">外掛</a>頁面整體停用的元件，從一開 始就不會成為候選標籤。</p><h2 id="標籤順序" tabindex="-1">標籤順序 <a class="header-anchor" href="#標籤順序" aria-label="Permalink to &quot;標籤順序&quot;">​</a></h2><p>跟設定裡其它地方(見<a href="./favorites.html">我的最愛</a>)同一套上移/下移(也可以拖曳)排序清單，但管的是整 個面板標籤列——內建的兩個標籤(最近檔案、上次目錄)和所有目前可見的外掛標籤都在同一個平坦清單 裡，跟上面按外掛分組的「外掛標籤」不一樣。把某個標籤上移或下移，就能改變它在實際面板裡的位置； 這個清單裡從上到下的順序，對應面板裡從左到右的順序。</p><p>這裡只列出目前真的會顯示出來的標籤——上面被關掉的「最近檔案」/「上次目錄」，或者用 <strong>×</strong> 按鈕 關閉過的外掛標籤，在重新啟用/重新開啟之前都沒有順序可調。</p>',16)])])}const c=a(o,[["render",n]]);export{u as __pageData,c as default};
